import subprocess,time,os
def cap(w,h):
    SES="test1"
    subprocess.run(["tmux","kill-session","-t",SES],capture_output=True); time.sleep(0.15)
    subprocess.run(["tmux","new-session","-d","-s",SES,"-x",str(w),"-y",str(h),"-c","/tmp/repo1","/workspace/executable"],capture_output=True); time.sleep(0.6)
