// ----- Git helpers -----

fn collect_branches(repo: &Repository) -> Vec<BranchInfo> {
    let mut branches: Vec<BranchInfo> = Vec::new();
    if let Ok(mut iter) = repo.branches(Some(BranchType::Local)) {
        for item in iter.by_ref() {
            if let Ok((branch, _)) = item {
                let name = match branch.name() { Ok(Some(n)) => n.to_string(), _ => continue };
                let target = match branch.get().target() { Some(t) => t, None => continue };
                branches.push(BranchInfo { name, is_remote: false, paired_origin: false, is_head: branch.is_head(), target });
            }
        }
    }
    if let Ok(mut iter) = repo.branches(Some(BranchType::Remote)) {
        for item in iter.by_ref() {
            if let Ok((branch, _)) = item {
                if branch.get().is_symbolic() { continue; }
                let name = match branch.name() { Ok(Some(n)) => n.to_string(), _ => continue };
                if name.ends_with("/HEAD") { continue; }
                let target = match branch.get().target() { Some(t) => t, None => continue };
                // pairing with origin/<local>
                let mut paired = false;
                if let Some(rest) = name.strip_prefix("origin/") {
                    if let Some(local) = branches.iter_mut().find(|b| !b.is_remote && b.name == rest && b.target == target) {
                        local.paired_origin = true;
                        paired = true;
                    }
                }
                if !paired {
                    branches.push(BranchInfo { name, is_remote: true, paired_origin: false, is_head: false, target });
                }
            }
        }
    }
    branches
}

fn current_branch_name(repo: &Repository) -> Option<String> {
    let head = repo.head().ok()?;
    if head.is_branch() {
        head.shorthand().map(|s| s.to_string())
    } else {
        Some("HEAD".to_string())
    }
}

fn repo_display_name(repo: &Repository) -> String {
    let path: PathBuf = repo.workdir().map(|p| p.to_path_buf()).unwrap_or_else(|| repo.path().to_path_buf());
    path.file_name().map(|s| s.to_string_lossy().to_string()).unwrap_or_else(|| path.to_string_lossy().to_string())
}

fn diff_file_stats(diff: &git2::Diff, idx: usize, delta: &git2::DiffDelta) -> Option<(usize, usize)> {
    if delta.flags().contains(DiffFlags::BINARY) { return None; }
    match git2::Patch::from_diff(diff, idx) {
        Ok(Some(patch)) => {
            if patch.delta().flags().contains(DiffFlags::BINARY) { return None; }
            match patch.line_stats() {
                Ok((_ctx, add, del)) => Some((add, del)),
                Err(_) => None,
            }
        }
        _ => None,
    }
}

fn file_change_from_delta(diff: &git2::Diff, idx: usize, delta: &git2::DiffDelta) -> FileChange {
    let path = delta.new_file().path()
        .or_else(|| delta.old_file().path())
        .map(|p| p.to_string_lossy().to_string())
        .unwrap_or_default();
    let stats = diff_file_stats(diff, idx, delta);
    FileChange { status: delta.status(), path, stats }
}

fn changed_files_for_commit(repo: &Repository, commit: &CommitInfo) -> ChangedData {
    let empty = ChangedData { count: 0, insertions: 0, deletions: 0, files: Vec::new() };
    let commit_obj = match repo.find_commit(commit.id) { Ok(c) => c, Err(_) => return empty };
    let tree = match commit_obj.tree() { Ok(t) => t, Err(_) => return empty };
    let parent_tree = if let Some(first) = commit.parents.first() {
        match repo.find_commit(*first).and_then(|c| c.tree()) { Ok(t) => Some(t), Err(_) => None }
    } else { None };
    let diff = match repo.diff_tree_to_tree(parent_tree.as_ref(), Some(&tree), None) {
        Ok(d) => d, Err(_) => return empty,
    };
    let count = diff.deltas().len();
    let mut files = Vec::new();
    let mut ins = 0usize;
    let mut del = 0usize;
    for (idx, delta) in diff.deltas().enumerate() {
        if files.len() >= 50 { break; }
        let fc = file_change_from_delta(&diff, idx, &delta);
        if let Some((a, d)) = fc.stats { ins += a; del += d; }
        files.push(fc);
    }
    ChangedData { count, insertions: ins, deletions: del, files }
}

fn uncommitted_data(repo: &Repository) -> (ChangedData, usize) {
    // Build staged and workdir diffs
    let head_tree = repo.head().ok().and_then(|h| h.peel_to_tree().ok());
    let staged = repo.diff_tree_to_index(head_tree.as_ref(), None, None).ok();
    let mut opts = DiffOptions::new();
    opts.include_untracked(false);
    let workdir = repo.diff_index_to_workdir(None, Some(&mut opts)).ok();
    let mut files: Vec<FileChange> = Vec::new();
    let mut seen_files: HashSet<String> = HashSet::new();
    let mut all_paths: HashSet<String> = HashSet::new();
    let mut ins = 0usize;
    let mut del = 0usize;
    for diff in [staged, workdir].into_iter().flatten() {
        for (idx, delta) in diff.deltas().enumerate() {
            let fc = file_change_from_delta(&diff, idx, &delta);
            all_paths.insert(fc.path.clone());
            if files.len() >= 50 { break; }
            if let Some((a, d)) = fc.stats { ins += a; del += d; }
            if seen_files.insert(fc.path.clone()) {
                files.push(fc);
            }
        }
    }
    let unique_count = all_paths.len();
    (ChangedData { count: files.len(), insertions: ins, deletions: del, files }, unique_count)
}

// ----- Graph builder -----

#[derive(Clone)]
struct Lane {
    target: Option<Oid>,
    color: Color,
}

struct GraphBuilder {
    lanes: Vec<Lane>,
    sub_color_idx: usize,
}
impl GraphBuilder {
    fn new() -> Self { Self { lanes: Vec::new(), sub_color_idx: 0 } }
    fn color_for_slot(&mut self, slot: usize) -> Color {
        if slot == 0 { Color::LightBlue } else {
            let c = PALETTE_SUB[self.sub_color_idx % PALETTE_SUB.len()];
            self.sub_color_idx += 1;
            c
        }
    }
    fn allocate_lane(&mut self) -> usize {
        if let Some(i) = self.lanes.iter().position(|l| l.target.is_none()) {
            let c = self.color_for_slot(i);
            self.lanes[i].color = c;
            i
        } else {
            let idx = self.lanes.len();
            let c = self.color_for_slot(idx);
            self.lanes.push(Lane { target: None, color: c });
            idx
        }
    }
    fn build(&mut self, commits: &mut [CommitInfo]) -> Vec<DisplayRow> {
        let mut rows: Vec<DisplayRow> = Vec::new();
        for ci in 0..commits.len() {
            let commit_id = commits[ci].id;
            let parents = commits[ci].parents.clone();
            // find lane column
            let mut col_opt = self.lanes.iter().position(|l| l.target == Some(commit_id));
            if col_opt.is_none() {
                let idx = self.allocate_lane();
                // mark lane as occupied by this commit temporarily (target will be updated to parent below)
                self.lanes[idx].target = Some(commit_id);
                col_opt = Some(idx);
            }
            let col = col_opt.unwrap();
            commits[ci].lane = col;
            commits[ci].lane_color = self.lanes[col].color;

            // Determine number of lane positions to draw: at least lanes len, may grow with extra parents.
            // First process extra parents to know final lanes count and capture connections.
            // Connections: list of (target_slot, is_new)
            let mut connections: Vec<(usize, bool)> = Vec::new();
            for extra in parents.iter().skip(1) {
                if let Some(e) = self.lanes.iter().position(|l| l.target == Some(*extra)) {
                    connections.push((e, false));
                } else {
                    let e = self.allocate_lane();
                    self.lanes[e].target = Some(*extra);
                    connections.push((e, true));
                }
            }
            // update first parent
            if let Some(first) = parents.first() {
                self.lanes[col].target = Some(*first);
            } else {
                self.lanes[col].target = None;
            }

            // build graph chars: positions 0..lanes_len*2-1
            let lane_count = self.lanes.len();
            let width = if lane_count == 0 { 1 } else { lane_count * 2 - 1 };
            let mut chars: Vec<(char, Option<Color>)> = vec![(' ', None); width];
            // base verticals
            for (i, lane) in self.lanes.iter().enumerate() {
                if lane.target.is_some() || i == col {
                    // placeholder, node handled below; active lanes vertical
                    chars[i * 2] = ('│', Some(lane.color));
                }
            }
            // node char
            let node_char = if commits[ci].is_head { '◉' } else { '●' };
            chars[col * 2] = (node_char, Some(self.lanes[col].color));

            // draw connections for extra parents
            for (target_slot, is_new) in connections.iter().cloned() {
                if target_slot == col { continue; }
                let target_color = self.lanes[target_slot].color;
                let lo = col.min(target_slot);
                let hi = col.max(target_slot);
                // horizontal separators and intermediate lane slots
                for pos in (lo * 2 + 1)..(hi * 2) {
                    if pos % 2 == 1 {
                        chars[pos] = ('─', Some(target_color));
                    } else {
                        let slot = pos / 2;
                        if slot != col && slot != target_slot {
                            if self.lanes[slot].target.is_some() {
                                let c = self.lanes[slot].color;
                                chars[pos] = ('┼', Some(c));
                            } else {
                                chars[pos] = ('─', Some(target_color));
                            }
                        }
                    }
                }
                // target glyph
                if is_new {
                    chars[target_slot * 2] = (if target_slot > col { '╮' } else { '╭' }, Some(target_color));
                } else {
                    chars[target_slot * 2] = (if target_slot > col { '┤' } else { '├' }, Some(target_color));
                }
            }

            // trim trailing spaces for graph storage
            let mut g = chars.clone();
            while g.len() > 1 {
                if g.last().map(|(c, _)| *c) == Some(' ') { g.pop(); } else { break; }
            }
            rows.push(DisplayRow { kind: RowKind::Commit(ci), graph: g });

            // connector row if next commit is targeted by multiple lanes
            if ci + 1 < commits.len() {
                let next_id = commits[ci + 1].id;
                let dup_slots: Vec<usize> = self.lanes.iter().enumerate()
                    .filter(|(_, l)| l.target == Some(next_id))
                    .map(|(i, _)| i).collect();
                if dup_slots.len() >= 2 {
                    let left = *dup_slots.first().unwrap();
                    let right = *dup_slots.last().unwrap();
                    let right_color = self.lanes[right].color;
                    let lane_count2 = self.lanes.len();
                    let width2 = if lane_count2 == 0 { 1 } else { lane_count2 * 2 - 1 };
                    let mut cchars: Vec<(char, Option<Color>)> = vec![(' ', None); width2];
                    // base verticals
                    for (i, lane) in self.lanes.iter().enumerate() {
                        if lane.target.is_some() {
                            cchars[i * 2] = ('│', Some(lane.color));
                        }
                    }
                    // horizontal line
                    for pos in (left * 2)..=(right * 2) {
                        if pos % 2 == 1 {
                            cchars[pos] = ('─', Some(right_color));
                        } else {
                            let slot = pos / 2;
                            if slot == left {
                                cchars[pos] = ('├', Some(self.lanes[left].color));
                            } else if slot == right {
                                cchars[pos] = ('╯', Some(self.lanes[right].color));
                            } else if dup_slots.contains(&slot) {
                                cchars[pos] = ('┴', Some(self.lanes[slot].color));
                            } else if self.lanes[slot].target.is_some() {
                                cchars[pos] = ('┼', Some(self.lanes[slot].color));
                            } else {
                                cchars[pos] = ('─', Some(right_color));
                            }
                        }
                    }
                    let mut gg = cchars.clone();
                    while gg.len() > 1 {
                        if gg.last().map(|(c, _)| *c) == Some(' ') { gg.pop(); } else { break; }
                    }
                    rows.push(DisplayRow { kind: RowKind::Connector, graph: gg });
                    // clear duplicate lanes except left
                    for slot in dup_slots.iter().skip(1) {
                        self.lanes[*slot].target = None;
                    }
                }
            }
        }
        rows
    }
}

// ----- Fuzzy -----
fn fuzzy_match(query: &str, target: &str) -> Option<(i32, Vec<usize>)> {
    let q_chars: Vec<char> = query.chars().collect();
    let t_chars: Vec<char> = target.chars().collect();
    if q_chars.is_empty() { return Some((0, Vec::new())); }
    let case_sensitive = query.chars().any(|c| c.is_uppercase());
    let eq = |a: char, b: char| -> bool {
        if case_sensitive { a == b } else { a.to_lowercase().next().unwrap_or(a) == b.to_lowercase().next().unwrap_or(b) }
    };
    let mut matched: Vec<usize> = Vec::new();
    let mut qi = 0usize;
    for (ti, tc) in t_chars.iter().enumerate() {
        if qi < q_chars.len() && eq(q_chars[qi], *tc) {
            matched.push(ti);
            qi += 1;
        }
    }
    if qi < q_chars.len() { return None; }
    let mut score: i32 = 0;
    let mut prev: Option<usize> = None;
    for (order, &idx) in matched.iter().enumerate() {
        score += 12;
        let boundary = if idx == 0 { true } else {
            let p = t_chars[idx - 1];
            matches!(p, '/' | '-' | '_' | '.' | ' ') || (p.is_lowercase() && t_chars[idx].is_uppercase())
        };
        if boundary {
            score += 10;
            if order == 0 { score += 5; }
        }
        if order == 0 {
            score -= (idx as i32) * 3;
        } else if let Some(pr) = prev {
            if idx == pr + 1 { score += 6; } else { score -= ((idx - pr - 1) as i32) * 2; }
        }
        prev = Some(idx);
    }
    score -= (t_chars.len() as i32 - q_chars.len() as i32);
    if let Some(&last) = matched.last() {
        score -= (t_chars.len() as i32 - 1 - last as i32);
    }
    Some((score, matched))
}

// ----- App -----
struct App {
    repo: Repository,
    config: Config,
    repo_name: String,
    current_branch: Option<String>,
    branches_all: Vec<BranchInfo>,
    commits: Vec<CommitInfo>,
    rows: Vec<DisplayRow>,
    max_graph_width: usize,
    selected: usize,
    branch_index: usize,
    list_state: ListState,
    changed_panel: Option<ChangedData>,
    uncommitted: Option<ChangedData>,
    uncommitted_count: usize,
    mode: Mode,
    input: String,
    confirm_branch_name: Option<String>,
    search_query: String,
    search_results: Vec<SearchResult>,
    search_index: usize,
    search_saved: (usize, usize),
    error_message: Option<String>,
    status_message: Option<String>,
    should_quit: bool,
}

impl App {
    fn new(repo: Repository, config: Config) -> Self {
        let mut app = Self {
            repo_name: repo_display_name(&repo),
            current_branch: None,
            branches_all: Vec::new(),
            commits: Vec::new(),
            rows: Vec::new(),
            max_graph_width: 1,
            selected: 0,
            branch_index: 0,
            list_state: ListState::default(),
            changed_panel: None,
            uncommitted: None,
            uncommitted_count: 0,
            mode: Mode::Normal,
            input: String::new(),
            confirm_branch_name: None,
            search_query: String::new(),
            search_results: Vec::new(),
            search_index: 0,
            search_saved: (0, 0),
            error_message: None,
            status_message: None,
            should_quit: false,
            repo,
            config,
        };
        app.load_data();
        app
    }

    fn selected_commit_index(&self) -> Option<usize> {
        self.rows.get(self.selected).and_then(|r| match r.kind {
            RowKind::Commit(ci) => Some(ci),
            _ => None,
        })
    }
    fn selected_commit(&self) -> Option<&CommitInfo> {
        self.selected_commit_index().map(|ci| &self.commits[ci])
    }

    fn load_data(&mut self) {
        // preserve selected branch name for the selected commit
        let preserved_branch_name: Option<String> = self.selected_commit()
            .and_then(|c| c.branches.get(self.branch_index).map(|b| b.name.clone()));
        let preserved_selected = self.selected;

        self.repo_name = repo_display_name(&self.repo);
        self.current_branch = current_branch_name(&self.repo);
        self.branches_all = collect_branches(&self.repo);

        // revwalk
        let mut commits: Vec<CommitInfo> = Vec::new();
        if let Ok(mut walk) = self.repo.revwalk() {
            let _ = walk.set_sorting(Sort::TOPOLOGICAL | Sort::TIME);
            for b in &self.branches_all {
                let _ = walk.push(b.target);
            }
            for oid_res in walk.take(500) {
                if let Ok(oid) = oid_res {
                    if let Ok(commit) = self.repo.find_commit(oid) {
                        let author = commit.author();
                        commits.push(CommitInfo {
                            id: oid,
                            subject: commit.summary().unwrap_or("").to_string(),
                            message: commit.message().unwrap_or("").to_string(),
                            author_name: author.name().unwrap_or("").to_string(),
                            author_email: author.email().unwrap_or("").to_string(),
                            timestamp: commit.time().seconds(),
                            parents: commit.parent_ids().collect(),
                            branches: Vec::new(),
                            lane: 0,
                            lane_color: Color::LightBlue,
                            is_head: false,
                        });
                    }
                }
            }
        }
        // branches per commit
        for c in commits.iter_mut() {
            let mut list: Vec<BranchInfo> = self.branches_all.iter().filter(|b| b.target == c.id).cloned().collect();
            if let Some(pos) = list.iter().position(|b| b.is_head) {
                let head_branch = list.remove(pos);
                list.insert(0, head_branch);
            }
            c.is_head = list.iter().any(|b| b.is_head);
            c.branches = list;
        }

        let mut builder = GraphBuilder::new();
        let mut graph_rows = builder.build(&mut commits);
        self.max_graph_width = graph_rows.iter().map(|r| r.graph.len()).max().unwrap_or(1).max(1);
        self.commits = commits;

        // uncommitted
        let (unc_data, unc_count) = uncommitted_data(&self.repo);
        self.uncommitted_count = unc_count;
        self.uncommitted = if unc_count > 0 { Some(unc_data) } else { None };

        let mut rows: Vec<DisplayRow> = Vec::new();
        if self.uncommitted.is_some() {
            rows.push(DisplayRow { kind: RowKind::Uncommitted, graph: vec![('●', Some(Color::DarkGray))] });
            self.max_graph_width = self.max_graph_width.max(1);
        }
        rows.append(&mut graph_rows);
        self.rows = rows;

        // restore selection
        if self.rows.is_empty() {
            self.selected = 0;
            self.list_state.select(None);
        } else {
            self.selected = preserved_selected.min(self.rows.len() - 1);
            self.list_state.select(Some(self.selected));
        }
        // restore branch index by name if possible, else clamp
        if let Some(c) = self.selected_commit() {
            if c.branches.is_empty() {
                self.branch_index = 0;
            } else if let Some(name) = preserved_branch_name {
                if let Some(pos) = c.branches.iter().position(|b| b.name == name) {
                    self.branch_index = pos;
                } else {
                    self.branch_index = self.branch_index.min(c.branches.len() - 1);
                }
            } else {
                self.branch_index = self.branch_index.min(c.branches.len() - 1);
            }
        } else {
            self.branch_index = 0;
        }
        // changed panel: reset first (reload semantics)
        self.changed_panel = None;
        self.update_changed_on_selection(true);
    }

    fn update_changed_on_selection(&mut self, is_reload: bool) {
        // is_reload=true: connector/none clears panel; false: connector preserves stale panel
        match self.rows.get(self.selected).map(|r| r.kind.clone()) {
            Some(RowKind::Commit(ci)) => {
                let commit = self.commits[ci].clone();
                self.changed_panel = Some(changed_files_for_commit(&self.repo, &commit));
            }
            Some(RowKind::Uncommitted) => {
                self.changed_panel = self.uncommitted.clone();
            }
            Some(RowKind::Connector) => {
                if is_reload { self.changed_panel = None; }
            }
            None => {
                self.changed_panel = None;
            }
        }
    }

    fn set_selection(&mut self, idx: usize, branch_idx: usize) {
        if self.rows.is_empty() { self.selected = 0; self.list_state.select(None); return; }
        self.selected = idx.min(self.rows.len() - 1);
        self.branch_index = branch_idx;
        self.list_state.select(Some(self.selected));
        // clamp branch index
        if let Some(c) = self.selected_commit() {
            if c.branches.is_empty() { self.branch_index = 0; }
            else { self.branch_index = self.branch_index.min(c.branches.len() - 1); }
        } else {
            // for connector/uncommitted keep branch_index as given? original resets except search restore; use 0 for normal movement
        }
        self.update_changed_on_selection(false);
    }

    fn move_down(&mut self) {
        if self.rows.is_empty() { return; }
        let n = (self.selected + 1).min(self.rows.len() - 1);
        self.set_selection(n, 0);
    }
    fn move_up(&mut self) {
        let n = self.selected.saturating_sub(1);
        self.set_selection(n, 0);
    }
    fn move_top(&mut self) { self.set_selection(0, 0); }
    fn move_bottom(&mut self) {
        if self.rows.is_empty() { return; }
        let n = self.rows.len() - 1;
        self.set_selection(n, 0);
    }
    fn page_down(&mut self) {
        if self.rows.is_empty() { return; }
        let n = (self.selected + 10).min(self.rows.len() - 1);
        self.set_selection(n, 0);
    }
    fn page_up(&mut self) {
        let n = self.selected.saturating_sub(10);
        self.set_selection(n, 0);
    }

    fn branch_occurrences(&self) -> Vec<(usize, usize)> {
        let mut out = Vec::new();
        for (ri, row) in self.rows.iter().enumerate() {
            if let RowKind::Commit(ci) = row.kind {
                for bi in 0..self.commits[ci].branches.len() {
                    out.push((ri, bi));
                }
            }
        }
        out
    }
    fn next_branch_occurrence(&mut self) {
        let occ = self.branch_occurrences();
        if occ.is_empty() { return; }
        let cur = occ.iter().position(|&(r, b)| r == self.selected && b == self.branch_index);
        let target = match cur { Some(p) => (p + 1).min(occ.len() - 1), None => 0 };
        let (r, b) = occ[target];
        self.set_selection(r, b);
    }
    fn prev_branch_occurrence(&mut self) {
        let occ = self.branch_occurrences();
        if occ.is_empty() { return; }
        let cur = occ.iter().position(|&(r, b)| r == self.selected && b == self.branch_index);
        let target = match cur { Some(p) => p.saturating_sub(1), None => occ.len() - 1 };
        let (r, b) = occ[target];
        self.set_selection(r, b);
    }
    fn jump_to_head(&mut self) {
        for (ri, row) in self.rows.iter().enumerate() {
            if let RowKind::Commit(ci) = row.kind {
                if let Some(pos) = self.commits[ci].branches.iter().position(|b| b.is_head) {
                    self.set_selection(ri, pos);
                    return;
                }
            }
        }
    }

    fn show_error(&mut self, msg: String) { self.error_message = Some(msg); }

    // Git operations
    fn checkout_selected(&mut self) {
        let (commit_id, entry_opt) = match self.selected_commit() {
            Some(c) => {
                let e = if c.branches.is_empty() { None } else { Some(c.branches[self.branch_index.min(c.branches.len() - 1)].clone()) };
                (c.id, e)
            }
            None => return,
        };
        let result: Result<()> = (|| {
            if let Some(entry) = entry_opt {
                if entry.is_remote {
                    // remote checkout
                    let local_name = entry.name.split_once('/').map(|(_, rest)| rest.to_string()).unwrap_or_else(|| entry.name.clone());
                    if let Ok(mut local) = self.repo.find_branch(&local_name, BranchType::Local) {
                        local.get_mut().set_target(commit_id, "")?;
                        return checkout_local_branch(&self.repo, &local);
                    } else {
                        let commit = self.repo.find_commit(commit_id)?;
                        let mut new_branch = self.repo.branch(&local_name, &commit, false)?;
                        new_branch.set_upstream(Some(&entry.name))?;
                        return checkout_local_branch(&self.repo, &new_branch);
                    }
                } else {
                    let branch = self.repo.find_branch(&entry.name, BranchType::Local)?;
                    return checkout_local_branch(&self.repo, &branch);
                }
            } else {
                let commit = self.repo.find_commit(commit_id)?;
                let obj = commit.as_object();
                let mut cb = CheckoutBuilder::new();
                cb.safe();
                self.repo.checkout_tree(obj, Some(&mut cb))?;
                self.repo.set_head_detached(commit_id)?;
                Ok(())
            }
        })();
        match result {
            Ok(()) => self.load_data(),
            Err(e) => self.show_error(e.to_string()),
        }
    }

    fn delete_selected_branch(&mut self) {
        if let Some(name) = self.confirm_branch_name.clone() {
            let res: Result<()> = (|| {
                let mut branch = self.repo.find_branch(&name, BranchType::Local)?;
                branch.delete()?;
                Ok(())
            })();
            match res {
                Ok(()) => self.load_data(),
                Err(e) => self.show_error(e.to_string()),
            }
        }
    }

    fn create_branch(&mut self, name: &str) {
        if name.is_empty() { return; }
        let commit_id = match self.selected_commit() { Some(c) => c.id, None => return };
        let commit = match self.repo.find_commit(commit_id) { Ok(c) => c, Err(_) => return };
        match self.repo.branch(name, &commit, false) {
            Ok(_) => self.load_data(),
            Err(_) => self.show_error(format!("Failed to create branch '{}'", name)),
        }
    }

    fn do_fetch(&mut self, manual: bool) {
        let dir: PathBuf = self.repo.workdir().map(|p| p.to_path_buf()).unwrap_or_else(|| self.repo.path().to_path_buf());
        let output = Command::new("git").arg("fetch").arg("origin").current_dir(&dir).output();
        match output {
            Ok(out) if out.status.success() => {
                self.status_message = Some("Fetched from origin".to_string());
                self.load_data();
            }
            Ok(out) => {
                if manual {
                    let stderr = String::from_utf8_lossy(&out.stderr).replace('\n', "");
                    self.show_error(format!("git fetch failed: {}", stderr));
                }
            }
            Err(e) => {
                if manual {
                    self.show_error(format!("git fetch failed: {}", e));
                }
            }
        }
    }

    // Search
    fn open_search(&mut self) {
        self.search_saved = (self.selected, self.branch_index);
        self.search_query = String::new();
        self.search_results = Vec::new();
        self.search_index = 0;
        self.mode = Mode::Search;
    }
    fn update_search_results(&mut self) {
        if self.search_query.is_empty() {
            self.search_results = Vec::new();
            self.search_index = 0;
            return;
        }
        let mut results: Vec<SearchResult> = Vec::new();
        let mut seen: HashSet<String> = HashSet::new();
        for (ri, row) in self.rows.iter().enumerate() {
            if let RowKind::Commit(ci) = row.kind {
                for (bi, entry) in self.commits[ci].branches.iter().enumerate() {
                    if !seen.insert(entry.name.clone()) { continue; }
                    if let Some((score, matched)) = fuzzy_match(&self.search_query, &entry.name) {
                        results.push(SearchResult { name: entry.name.clone(), row_index: ri, branch_index: bi, score, matched });
                    }
                }
            }
        }
        results.sort_by(|a, b| b.score.cmp(&a.score));
        self.search_results = results;
        self.search_index = 0;
        if let Some(first) = self.search_results.first().cloned() {
            self.set_selection(first.row_index, first.branch_index);
        }
    }
    fn jump_to_search_result(&mut self) {
        if let Some(r) = self.search_results.get(self.search_index).cloned() {
            self.set_selection(r.row_index, r.branch_index);
        }
    }
    fn search_next(&mut self) {
        if self.search_results.is_empty() { return; }
        self.search_index = (self.search_index + 1) % self.search_results.len();
        self.jump_to_search_result();
    }
    fn search_prev(&mut self) {
        if self.search_results.is_empty() { return; }
        if self.search_index == 0 { self.search_index = self.search_results.len() - 1; } else { self.search_index -= 1; }
        self.jump_to_search_result();
    }
    fn cancel_search(&mut self) {
        let (sel, bi) = self.search_saved;
        self.mode = Mode::Normal;
        self.set_selection(sel, bi);
    }

    fn handle_key(&mut self, key: KeyEvent) {
        // error interception
        if self.error_message.is_some() {
            match key.code {
                KeyCode::Esc | KeyCode::Enter => { self.error_message = None; }
                KeyCode::Char('q') => { self.error_message = None; }
                _ => {}
            }
            return;
        }
        match self.mode {
            Mode::Help => {
                match key.code {
                    KeyCode::Esc | KeyCode::Char('q') | KeyCode::Char('?') => { self.mode = Mode::Normal; }
                    _ => {}
                }
            }
            Mode::CreateBranch => {
                match key.code {
                    KeyCode::Esc => { self.mode = Mode::Normal; }
                    KeyCode::Enter => {
                        let name = self.input.clone();
                        self.mode = Mode::Normal;
                        self.create_branch(&name);
                    }
                    KeyCode::Backspace => { self.input.pop(); }
                    KeyCode::Char(c) => { self.input.push(c); }
                    _ => {}
                }
            }
            Mode::ConfirmDelete => {
                match key.code {
                    KeyCode::Enter | KeyCode::Char('y') => {
                        self.mode = Mode::Normal;
                        self.delete_selected_branch();
                        self.confirm_branch_name = None;
                    }
                    KeyCode::Esc | KeyCode::Char('n') => {
                        self.mode = Mode::Normal;
                        self.confirm_branch_name = None;
                    }
                    _ => {}
                }
            }
            Mode::Search => {
                // ctrl-j/k first
                if key.modifiers.contains(KeyModifiers::CONTROL) {
                    match key.code {
                        KeyCode::Char('j') => { self.search_next(); return; }
                        KeyCode::Char('k') => { self.search_prev(); return; }
                        _ => {}
                    }
                }
                match key.code {
                    KeyCode::Esc => { self.cancel_search(); }
                    KeyCode::Enter => { self.mode = Mode::Normal; }
                    KeyCode::Backspace => {
                        if self.search_query.is_empty() {
                            self.cancel_search();
                        } else {
                            self.search_query.pop();
                            self.update_search_results();
                        }
                    }
                    KeyCode::Up => { self.search_prev(); }
                    KeyCode::Down => { self.search_next(); }
                    KeyCode::Char(c) => {
                        self.search_query.push(c);
                        self.update_search_results();
                    }
                    _ => {}
                }
            }
            Mode::Normal => {
                match key.code {
                    KeyCode::Char('d') if key.modifiers.contains(KeyModifiers::CONTROL) => { self.page_down(); }
                    KeyCode::Char('u') if key.modifiers.contains(KeyModifiers::CONTROL) => { self.page_up(); }
                    KeyCode::Char('q') | KeyCode::Esc => { self.should_quit = true; }
                    KeyCode::Char('j') | KeyCode::Down => { self.move_down(); }
                    KeyCode::Char('k') | KeyCode::Up => { self.move_up(); }
                    KeyCode::Char('h') | KeyCode::Left => {
                        if let Some(c) = self.selected_commit() {
                            if !c.branches.is_empty() {
                                self.branch_index = self.branch_index.saturating_sub(1);
                            }
                        }
                    }
                    KeyCode::Char('l') | KeyCode::Right => {
                        if let Some(c) = self.selected_commit() {
                            if !c.branches.is_empty() {
                                self.branch_index = (self.branch_index + 1).min(c.branches.len() - 1);
                            }
                        }
                    }
                    KeyCode::Char(']') | KeyCode::Tab => { self.next_branch_occurrence(); }
                    KeyCode::Char('[') | KeyCode::BackTab => { self.prev_branch_occurrence(); }
                    KeyCode::Char('g') | KeyCode::Home => { self.move_top(); }
                    KeyCode::Char('G') | KeyCode::End => { self.move_bottom(); }
                    KeyCode::Char('@') => { self.jump_to_head(); }
                    KeyCode::Char('b') => {
                        self.input = String::new();
                        self.mode = Mode::CreateBranch;
                    }
                    KeyCode::Char('d') => {
                        // delete only if selected branch is local and not head
                        if let Some(c) = self.selected_commit() {
                            if !c.branches.is_empty() {
                                let entry = c.branches[self.branch_index.min(c.branches.len() - 1)].clone();
                                if !entry.is_remote && !entry.is_head {
                                    self.confirm_branch_name = Some(entry.name.clone());
                                    self.mode = Mode::ConfirmDelete;
                                }
                            }
                        }
                    }
                    KeyCode::Char('f') => { self.do_fetch(true); }
                    KeyCode::Char('R') => { self.load_data(); }
                    KeyCode::Char('/') => { self.open_search(); }
                    KeyCode::Char('?') => { self.mode = Mode::Help; }
                    KeyCode::Enter => { self.checkout_selected(); }
                    _ => {}
                }
            }
        }
    }
}

fn checkout_local_branch(repo: &Repository, branch: &git2::Branch) -> Result<()> {
    let target = branch.get().target().context("branch has no target")?;
    let obj = repo.find_object(target, None)?;
    let mut cb = CheckoutBuilder::new();
    cb.safe();
    repo.checkout_tree(&obj, Some(&mut cb))?;
    let refname = branch.get().name().context("branch has no name")?;
    repo.set_head(refname)?;
    Ok(())
}

fn main() -> Result<()> {
    let _cli = Cli::parse();
    let repo = Repository::discover(".")
        .context("Git repository not found. Please run inside a Git repository.")?;
    let config = load_config();
    let repo_name_for_fetch = repo_display_name(&repo);
    let _ = repo_name_for_fetch;
    let mut app = App::new(repo, config);

    enable_raw_mode()?;
    let mut stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen)?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;

    let mut last_refresh = Instant::now();
    let mut last_fetch = Instant::now();
    let result: Result<()> = (|| {
        loop {
            terminal.draw(|frame| {
                let area = frame.area();
                render_app(&mut app, frame, area);
            })?;
            if app.should_quit { break; }
            if event::poll(Duration::from_millis(100))? {
                match event::read()? {
                    Event::Key(key) => {
                        app.handle_key(key);
                        if app.should_quit { break; }
                    }
                    _ => {}
                }
            }
            if app.config.refresh.auto_refresh
                && last_refresh.elapsed() >= Duration::from_secs(app.config.refresh.refresh_interval)
            {
                app.load_data();
                last_refresh = Instant::now();
            }
            if app.config.refresh.auto_fetch
                && last_fetch.elapsed() >= Duration::from_secs(app.config.refresh.fetch_interval)
            {
                app.do_fetch(false);
                last_fetch = Instant::now();
            }
        }
        Ok(())
    })();

    disable_raw_mode()?;
    execute!(terminal.backend_mut(), LeaveAlternateScreen)?;
    let _ = terminal.show_cursor();
    result
}

// ----- Rendering -----

fn centered_rect(percent_x: u16, percent_y: u16, r: Rect) -> Rect {
    let vertical = Layout::vertical([
        Constraint::Percentage((100 - percent_y) / 2),
        Constraint::Percentage(percent_y),
        Constraint::Percentage((100 - percent_y) / 2),
    ]).split(r);
    let horizontal = Layout::horizontal([
        Constraint::Percentage((100 - percent_x) / 2),
        Constraint::Percentage(percent_x),
        Constraint::Percentage((100 - percent_x) / 2),
    ]).split(vertical[1]);
    horizontal[1]
}

fn block_dark(title: &str) -> Block<'_> {
    Block::default()
        .title(title.to_string())
        .borders(Borders::ALL)
        .border_style(Style::default().fg(Color::DarkGray))
}

fn render_app(app: &mut App, frame: &mut Frame, area: Rect) {
    if area.width < 20 || area.height < 6 {
        let msg = format!("Terminal too small ({}x{}). Need at least 20x6.", area.width, area.height);
        let p = Paragraph::new(msg).style(Style::default().fg(Color::Red));
        frame.render_widget(p, area);
        return;
    }
    let chunks = Layout::vertical([
        Constraint::Percentage(70),
        Constraint::Percentage(30),
        Constraint::Length(1),
    ]).split(area);
    let commits_area = chunks[0];
    let detail_area = chunks[1];
    let status_area = chunks[2];

    // Commits list
    render_commits(app, frame, commits_area);

    // Detail areas
    let detail_chunks: Vec<Rect> = if detail_area.width >= 57 {
        Layout::horizontal([Constraint::Percentage(50), Constraint::Percentage(50)]).split(detail_area).to_vec()
    } else {
        Layout::vertical([Constraint::Percentage(50), Constraint::Percentage(50)]).split(detail_area).to_vec()
    };
    render_detail(app, frame, detail_chunks[0]);
    render_changed(app, frame, detail_chunks[1]);

    // Branches popup (above commits, below other popups)
    render_branches_popup(app, frame, commits_area);

    // Status
    render_status(app, frame, status_area);

    // Popups
    match app.mode {
        Mode::Help => render_help(frame, area),
        Mode::CreateBranch => render_create_branch(app, frame, area),
        Mode::ConfirmDelete => render_confirm(app, frame, area),
        Mode::Search => render_search(app, frame, area),
        Mode::Normal => {}
    }
}

fn commit_row_line(app: &App, row_index: usize, inner_width: usize) -> Line<'static> {
    let row = &app.rows[row_index];
    let is_selected = row_index == app.selected;
    let mut spans: Vec<Span<'static>> = Vec::new();
    spans.push(Span::raw(" "));
    // graph
    for pos in 0..app.max_graph_width {
        if pos < row.graph.len() {
            let (ch, color) = row.graph[pos];
            let mut st = Style::default().add_modifier(Modifier::BOLD);
            if let Some(c) = color { st = st.fg(c); }
            if ch == ' ' {
                spans.push(Span::raw(" "));
            } else {
                spans.push(Span::styled(ch.to_string(), st));
            }
        } else {
            spans.push(Span::raw(" "));
        }
    }
    spans.push(Span::raw("  "));

    let graph_offset = 1 + app.max_graph_width + 2;

    // left text and meta
    match row.kind {
        RowKind::Uncommitted => {
            let text = format!("uncommitted changes ({})", app.uncommitted_count);
            spans.push(Span::styled(text, Style::default().fg(Color::White)));
        }
        RowKind::Connector => {
            // nothing
        }
        RowKind::Commit(ci) => {
            let commit = &app.commits[ci];
            // meta visibility
            let g = app.max_graph_width;
            let show_author = inner_width >= g + 64;
            let show_date = inner_width >= g + 75;
            let show_hash = inner_width >= g + 84;
            let date_str = format_date(commit.timestamp);
            let author_str = author_field(&commit.author_name);
            let hash_str = short_id(commit.id);
            let mut meta_width = 0usize;
            if show_date { meta_width += 10; }
            if show_author { if show_date { meta_width += 2; } meta_width += UnicodeWidthStr::width(author_str.as_str()); }
            if show_hash { if show_date || show_author { meta_width += 2; } meta_width += 7; }
            if show_date || show_author || show_hash { meta_width += 1; } // trailing space
            let left_avail = inner_width.saturating_sub(graph_offset).saturating_sub(meta_width);

            // label
            let mut left_text_width = 0usize;
            let mut label_span: Option<Span<'static>> = None;
            if !commit.branches.is_empty() {
                let bi = if is_selected { app.branch_index.min(commit.branches.len() - 1) } else { 0 };
                let entry = &commit.branches[bi];
                let label_text = if commit.branches.len() == 1 {
                    if entry.paired_origin { format!("[{} ↔ origin]", entry.name) } else { format!("[{}]", entry.name) }
                } else {
                    format!("[{}] +{}", entry.name, commit.branches.len() - 1)
                };
                let color = if is_selected { Color::Black } else { commit.lane_color };
                left_text_width += UnicodeWidthStr::width(label_text.as_str()) + 1; // plus following space
                label_span = Some(Span::styled(label_text, Style::default().fg(color).add_modifier(Modifier::BOLD)));
            }
            if let Some(ls) = label_span {
                spans.push(ls);
                spans.push(Span::raw(" "));
            }
            let subject_avail = left_avail.saturating_sub(left_text_width);
            let subject = truncate_to_width(&commit.subject, subject_avail);
            let subj_w = UnicodeWidthStr::width(subject.as_str());
            spans.push(Span::raw(subject));
            // padding to meta
            let used_left = left_text_width + subj_w;
            if used_left < left_avail {
                spans.push(Span::raw(" ".repeat(left_avail - used_left)));
            }
            // meta spans
            let mut first_meta = true;
            if show_date {
                if !first_meta { spans.push(Span::raw("  ")); }
                spans.push(Span::styled(date_str, Style::default().fg(Color::DarkGray)));
                first_meta = false;
            }
            if show_author {
                if !first_meta { spans.push(Span::raw("  ")); }
                spans.push(Span::styled(author_str, Style::default().fg(Color::Cyan)));
                first_meta = false;
            }
            if show_hash {
                if !first_meta { spans.push(Span::raw("  ")); }
                spans.push(Span::styled(hash_str, Style::default().fg(Color::Yellow)));
                first_meta = false;
            }
            if show_date || show_author || show_hash {
                spans.push(Span::raw(" "));
            }
            let _ = first_meta;
        }
    }
    Line::from(spans)
}

fn render_commits(app: &mut App, frame: &mut Frame, area: Rect) {
    let inner_width = area.width.saturating_sub(2) as usize;
    let items: Vec<ListItem> = (0..app.rows.len())
        .map(|i| ListItem::new(commit_row_line(app, i, inner_width)))
        .collect();
    let list = List::new(items)
        .block(block_dark(" Commits "))
        .highlight_style(Style::default().bg(Color::DarkGray).add_modifier(Modifier::BOLD));
    // ensure state selected
    if app.rows.is_empty() {
        app.list_state.select(None);
    } else {
        app.list_state.select(Some(app.selected.min(app.rows.len() - 1)));
    }
    frame.render_stateful_widget(list, area, &mut app.list_state);
}

fn render_detail(app: &App, frame: &mut Frame, area: Rect) {
    let lines: Vec<Line<'static>> = if app.rows.is_empty() {
        vec![Line::from("Select a commit")]
    } else {
        match app.rows.get(app.selected).map(|r| &r.kind) {
            Some(RowKind::Connector) => vec![Line::from("(connector line)")],
            Some(RowKind::Uncommitted) => vec![
                Line::from(Span::styled("Uncommitted Changes", Style::default().add_modifier(Modifier::BOLD))),
                Line::from(""),
                Line::from(format!("{} files with changes", app.uncommitted_count)),
            ],
            Some(RowKind::Commit(ci)) => {
                let c = &app.commits[*ci];
                let mut lines: Vec<Line<'static>> = Vec::new();
                lines.push(Line::from(vec![
                    Span::styled("Commit: ", Style::default().add_modifier(Modifier::BOLD)),
                    Span::styled(c.id.to_string(), Style::default().fg(Color::Yellow)),
                ]));
                lines.push(Line::from(vec![
                    Span::styled("Author: ", Style::default().add_modifier(Modifier::BOLD)),
                    Span::styled(format!("{} <{}>", c.author_name, c.author_email), Style::default().fg(Color::Blue)),
                ]));
                lines.push(Line::from(vec![
                    Span::styled("Date:   ", Style::default().add_modifier(Modifier::BOLD)),
                    Span::styled(format_datetime(c.timestamp), Style::default().fg(Color::DarkGray)),
                ]));
                if !c.parents.is_empty() {
                    let parents = c.parents.iter().map(|p| short_id(*p)).collect::<Vec<_>>().join(", ");
                    lines.push(Line::from(vec![
                        Span::styled("Parent: ", Style::default().add_modifier(Modifier::BOLD)),
                        Span::styled(parents, Style::default().fg(Color::DarkGray)),
                    ]));
                }
                lines.push(Line::from(""));
                for l in c.message.lines() {
                    lines.push(Line::from(l.to_string()));
                }
                lines
            }
            None => vec![Line::from("Select a commit")],
        }
    };
    let p = Paragraph::new(lines).block(block_dark(" Commit Detail ")).wrap(Wrap { trim: true });
    frame.render_widget(p, area);
}

fn status_char_color(status: Delta) -> Color {
    match status {
        Delta::Added => Color::Green,
        Delta::Modified => Color::Yellow,
        Delta::Deleted => Color::Red,
        Delta::Renamed => Color::Cyan,
        Delta::Typechange => Color::Magenta,
        Delta::Copied => Color::Blue,
        _ => Color::White,
    }
}
fn status_char(status: Delta) -> char {
    match status {
        Delta::Added => 'A',
        Delta::Modified => 'M',
        Delta::Deleted => 'D',
        Delta::Renamed => 'R',
        Delta::Typechange => 'T',
        Delta::Copied => 'C',
        _ => '?',
    }
}

fn render_changed(app: &App, frame: &mut Frame, area: Rect) {
    let lines: Vec<Line<'static>> = match &app.changed_panel {
        None => Vec::new(),
        Some(data) => {
            let mut lines: Vec<Line<'static>> = Vec::new();
            lines.push(Line::from(vec![
                Span::styled(format!("{} files changed", data.count), Style::default().add_modifier(Modifier::BOLD)),
                Span::raw("  "),
                Span::styled(format!("+{}", data.insertions), Style::default().fg(Color::Green)),
                Span::raw(" "),
                Span::styled(format!("-{}", data.deletions), Style::default().fg(Color::Red)),
            ]));
            lines.push(Line::from(""));
            for f in &data.files {
                let mut spans: Vec<Span<'static>> = Vec::new();
                spans.push(Span::styled(format!(" {} ", status_char(f.status)), Style::default().fg(status_char_color(f.status))));
                spans.push(Span::raw(f.path.clone()));
                if let Some((a, d)) = f.stats {
                    spans.push(Span::raw(" "));
                    spans.push(Span::styled(format!("+{}", a), Style::default().fg(Color::Green)));
                    spans.push(Span::raw(" "));
                    spans.push(Span::styled(format!("-{}", d), Style::default().fg(Color::Red)));
                }
                lines.push(Line::from(spans));
            }
            lines
        }
    };
    let p = Paragraph::new(lines).block(block_dark(" Changed Files ")).wrap(Wrap { trim: true });
    frame.render_widget(p, area);
}

fn render_branches_popup(app: &App, frame: &mut Frame, commits_area: Rect) {
    if app.mode != Mode::Normal || app.error_message.is_some() { return; }
    let commit = match app.selected_commit() { Some(c) => c, None => return };
    if commit.branches.len() <= 1 { return; }
    let max_name_width = commit.branches.iter().map(|b| UnicodeWidthStr::width(b.name.as_str())).max().unwrap_or(0);
    let popup_width = (max_name_width + 6) as u16;
    let popup_height = (commit.branches.len() + 2) as u16;
    let offset = app.list_state.offset();
    let visible_selected = app.selected.saturating_sub(offset) as u16;
    let selected_screen_y = commits_area.y + 1 + visible_selected;
    let popup_y = if visible_selected < popup_height {
        selected_screen_y + 1
    } else {
        commits_area.y + 1
    };
    let popup_x = commits_area.x + commits_area.width.saturating_sub(popup_width + 2);
    let area = Rect::new(popup_x, popup_y, popup_width, popup_height);
    let lines: Vec<Line<'static>> = commit.branches.iter().enumerate().map(|(i, b)| {
        if i == app.branch_index.min(commit.branches.len() - 1) {
            Line::from(Span::styled(format!("▶ {}", b.name), Style::default().fg(Color::Black).bg(Color::Blue).add_modifier(Modifier::BOLD)))
        } else {
            Line::from(Span::styled(format!("  {}", b.name), Style::default().fg(Color::White)))
        }
    }).collect();
    let block = Block::default()
        .title(" Branches ")
        .borders(Borders::ALL)
        .border_style(Style::default().fg(Color::Blue))
        .style(Style::default().bg(Color::Black));
    let p = Paragraph::new(lines).block(block).style(Style::default().bg(Color::Black));
    frame.render_widget(Clear, area);
    frame.render_widget(p, area);
}

fn hint_spans(pairs: &[(&str, &str)]) -> Vec<Span<'static>> {
    let mut spans = Vec::new();
    for (i, (k, desc)) in pairs.iter().enumerate() {
        spans.push(Span::styled(format!(" {} ", k), Style::default().fg(Color::Black).bg(Color::Cyan).add_modifier(Modifier::BOLD)));
        let d = if i + 1 < pairs.len() { format!("{} ", desc) } else { desc.to_string() };
        spans.push(Span::styled(d, Style::default().fg(Color::White)));
    }
    spans
}

fn render_status(app: &App, frame: &mut Frame, area: Rect) {
    let mut left: Vec<Span<'static>> = Vec::new();
    left.push(Span::styled(format!(" {} ", app.repo_name), Style::default().fg(Color::Black).bg(Color::Magenta).add_modifier(Modifier::BOLD)));
    if let Some(branch) = &app.current_branch {
        left.push(Span::raw(" "));
        left.push(Span::styled(format!(" {} ", branch), Style::default().fg(Color::Black).bg(Color::Green)));
    }
    left.push(Span::raw(" "));
    let mut badge: Option<String> = None;
    if let Some(err) = &app.error_message {
        left.push(Span::styled(format!(" {} ", err), Style::default().fg(Color::White).bg(Color::Red).add_modifier(Modifier::BOLD)));
        left.push(Span::raw("  "));
        left.extend(hint_spans(&[("Esc/Enter", "close")]));
        badge = Some(" ERROR ".to_string());
    } else {
        match app.mode {
            Mode::Help => {
                left.extend(hint_spans(&[("Esc/q", "close help")]));
                badge = Some(" HELP ".to_string());
            }
            Mode::CreateBranch | Mode::Search => {
                left.extend(hint_spans(&[("Enter", "confirm"), ("Esc", "cancel")]));
                badge = Some(" INPUT ".to_string());
            }
            Mode::ConfirmDelete => {
                left.extend(hint_spans(&[("y", "yes"), ("n", "no")]));
                badge = Some(" CONFIRM ".to_string());
            }
            Mode::Normal => {
                if let Some(msg) = &app.status_message {
                    left.push(Span::styled(format!(" {} ", msg), Style::default().fg(Color::Black).bg(Color::Cyan).add_modifier(Modifier::BOLD)));
                } else {
                    left.extend(hint_spans(&[
                        ("j/k", "move"),
                        ("Enter", "checkout"),
                        ("b", "branch"),
                        ("f", "fetch"),
                        ("?", "help"),
                        ("q", "quit"),
                    ]));
                }
            }
        }
    }
    if let Some(b) = badge {
        let bw = UnicodeWidthStr::width(b.as_str()) as u16;
        let left_width = area.width.saturating_sub(bw);
        let left_area = Rect::new(area.x, area.y, left_width, 1);
        frame.render_widget(Paragraph::new(Line::from(left)), left_area);
        let badge_area = Rect::new(area.x + left_width, area.y, bw, 1);
        let bp = Paragraph::new(Line::from(Span::styled(b, Style::default().fg(Color::Black).bg(Color::Yellow).add_modifier(Modifier::BOLD))));
        frame.render_widget(bp, badge_area);
    } else {
        frame.render_widget(Paragraph::new(Line::from(left)), area);
    }
}

fn popup_block(title: &str, border_color: Color) -> Block<'static> {
    Block::default()
        .title(title.to_string())
        .borders(Borders::ALL)
        .border_style(Style::default().fg(border_color))
        .style(Style::default().bg(Color::Black))
}

fn render_help(frame: &mut Frame, area: Rect) {
    let popup = centered_rect(60, 70, area);
    let mut lines: Vec<Line<'static>> = Vec::new();
    let mut add_section = |lines: &mut Vec<Line<'static>>, title: &str, entries: &[(&str, &str)]| {
        lines.push(Line::from(Span::styled(title.to_string(), Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD))));
        for (k, desc) in entries {
            lines.push(Line::from(vec![
                Span::styled(format!("  {:<11}", k), Style::default().add_modifier(Modifier::BOLD)),
                Span::styled(desc.to_string(), Style::default().fg(Color::White)),
            ]));
        }
        lines.push(Line::from(""));
    };
    add_section(&mut lines, "Navigation", &[
        ("j / ↓", "Move down"),
        ("k / ↑", "Move up"),
        ("] / Tab", "Select next branch"),
        ("[ / S-Tab", "Select previous branch"),
        ("h / ←", "Select left branch (same commit)"),
        ("l / →", "Select right branch (same commit)"),
        ("Ctrl+d", "Page down"),
        ("Ctrl+u", "Page up"),
        ("g / Home", "Go to top"),
        ("G / End", "Go to bottom"),
        ("@", "Jump to HEAD (current branch)"),
    ]);
    add_section(&mut lines, "Git Operations", &[
        ("Enter", "Checkout selected branch/commit"),
        ("b", "Create new branch"),
        ("d", "Delete branch"),
        ("f", "Fetch from origin"),
    ]);
    add_section(&mut lines, "Search", &[
        ("/", "Search branches"),
        ("↑ / C-k", "Select previous result"),
        ("↓ / C-j", "Select next result"),
        ("Enter", "Jump to selected branch"),
        ("Esc", "Cancel search"),
    ]);
    // Other section without trailing processing via add_section (it adds a blank, which matches popup fill invisibly)
    add_section(&mut lines, "Other", &[
        ("R", "Refresh"),
        ("?", "Toggle this help"),
        ("q / Esc", "Quit"),
    ]);
    let p = Paragraph::new(lines).block(popup_block(" Help ", Color::Cyan)).style(Style::default().bg(Color::Black));
    frame.render_widget(Clear, popup);
    frame.render_widget(p, popup);
}

fn render_create_branch(app: &App, frame: &mut Frame, area: Rect) {
    let popup = centered_rect(50, 20, area);
    let lines: Vec<Line<'static>> = vec![
        Line::from(""),
        Line::from(vec![
            Span::raw("  "),
            Span::styled(app.input.clone(), Style::default().fg(Color::White).add_modifier(Modifier::UNDERLINED)),
            Span::styled("_", Style::default().fg(Color::Cyan)),
        ]),
        Line::from(""),
        Line::from(Span::styled("  Enter: confirm  Esc: cancel", Style::default().fg(Color::DarkGray))),
    ];
    let p = Paragraph::new(lines).block(popup_block(" New Branch Name ", Color::Cyan)).style(Style::default().bg(Color::Black));
    frame.render_widget(Clear, popup);
    frame.render_widget(p, popup);
}

fn render_confirm(app: &App, frame: &mut Frame, area: Rect) {
    let popup = centered_rect(50, 20, area);
    let name = app.confirm_branch_name.clone().unwrap_or_default();
    let lines: Vec<Line<'static>> = vec![
        Line::from(""),
        Line::from(Span::styled(format!("  Delete branch '{}'?", name), Style::default().fg(Color::White))),
        Line::from(""),
        Line::from(vec![
            Span::styled("  y", Style::default().fg(Color::Green).add_modifier(Modifier::BOLD)),
            Span::raw(": Yes  "),
            Span::styled("n", Style::default().fg(Color::Red).add_modifier(Modifier::BOLD)),
            Span::raw(": No"),
        ]),
    ];
    let p = Paragraph::new(lines).block(popup_block(" Confirm ", Color::Yellow)).style(Style::default().bg(Color::Black));
    frame.render_widget(Clear, popup);
    frame.render_widget(p, popup);
}

fn render_search(app: &App, frame: &mut Frame, area: Rect) {
    // width 60% centered horizontally
    let horiz = Layout::horizontal([
        Constraint::Percentage(20),
        Constraint::Percentage(60),
        Constraint::Percentage(20),
    ]).split(area);
    let x = horiz[1].x;
    let width = horiz[1].width;

    let inner_width = width.saturating_sub(2) as usize;
    let mut lines: Vec<Line<'static>> = Vec::new();
    lines.push(Line::from(vec![
        Span::raw("  "),
        Span::styled(app.search_query.clone(), Style::default().fg(Color::White).add_modifier(Modifier::UNDERLINED)),
        Span::styled("_", Style::default().fg(Color::Cyan)),
    ]));
    if app.search_query.is_empty() {
        lines.push(Line::from(Span::styled("  Enter: confirm  Esc: cancel", Style::default().fg(Color::DarkGray))));
    } else if app.search_results.is_empty() {
        lines.push(Line::from(Span::styled("  No matches", Style::default().fg(Color::DarkGray))));
    } else {
        lines.push(Line::from(Span::styled("─".repeat(inner_width), Style::default().fg(Color::DarkGray))));
        const MAX_VISIBLE: usize = 7;
        let total = app.search_results.len();
        let start = if total > MAX_VISIBLE {
            app.search_index.saturating_sub(MAX_VISIBLE - 1).min(total - MAX_VISIBLE)
        } else { 0 };
        let end = (start + MAX_VISIBLE).min(total);
        let visible_count = end - start;
        for (vi, ri) in (start..end).enumerate() {
            let result = &app.search_results[ri];
            let is_first = vi == 0;
            let is_last = vi + 1 == visible_count;
            let has_above = start > 0;
            let has_below = end < total;
            let is_selected = ri == app.search_index;
            let marker = if is_selected {
                if is_first && has_above { "▲ " } else if is_last && has_below { "▼ " } else { "▶ " }
            } else if is_first && has_above { "↑ " } else if is_last && has_below { "↓ " } else { "  " };
            if is_selected {
                lines.push(Line::from(vec![
                    Span::raw(marker.to_string()),
                    Span::styled(result.name.clone(), Style::default().fg(Color::Black).bg(Color::Cyan).add_modifier(Modifier::BOLD)),
                ]));
            } else {
                let matched_set: HashSet<usize> = result.matched.iter().cloned().collect();
                let mut spans: Vec<Span<'static>> = Vec::new();
                spans.push(Span::styled(marker.to_string(), Style::default().fg(Color::DarkGray)));
                for (idx, ch) in result.name.chars().enumerate() {
                    if matched_set.contains(&idx) {
                        spans.push(Span::styled(ch.to_string(), Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)));
                    } else {
                        spans.push(Span::styled(ch.to_string(), Style::default().fg(Color::White)));
                    }
                }
                lines.push(Line::from(spans));
            }
        }
        lines.push(Line::from(Span::styled("  ↑↓: select  Enter: jump  Esc: cancel", Style::default().fg(Color::DarkGray))));
    }
    let popup_height = (lines.len() + 2) as u16;
    let y = area.height.saturating_sub(popup_height + 1);
    let popup = Rect::new(x, y, width, popup_height);
    let p = Paragraph::new(lines).block(popup_block(" Search branches ", Color::Cyan)).style(Style::default().bg(Color::Black));
    frame.render_widget(Clear, popup);
    frame.render_widget(p, popup);
}
