                    i+=len(m.group(0))
                    if codes=='':
                        cur={'fg':None,'bg':None,'bold':False,'underline':False,'italic':False}
                    else:
                        parts=codes.split(';')
                        j=0
                        while j < len(parts):
                            c=int(parts[j]) if parts[j] else 0
                            if c==0: cur={'fg':None,'bg':None,'bold':False,'underline':False,'italic':False}
                            elif c==1: cur['bold']=True
                            elif c==4: cur['underline']=True
                            elif c==3: cur['italic']=True
                            elif c==22: cur['bold']=False
                            elif c==24: cur['underline']=False
                            elif c==39: cur['fg']=None
                            elif c==49: cur['bg']=None
                            elif c==38 and j+2 < len(parts) and parts[j+1]=='5': cur['fg']=int(parts[j+2]); j+=2
                            elif c==48 and j+2 < len(parts) and parts[j+1]=='5': cur['bg']=int(parts[j+2]); j+=2
                            j+=1
                    continue
                else:
                    i+=1; continue
            ch=line[i]; i+=1
            cells.append((ch, tuple(sorted(cur.items()))))
            w=2 if unicodedata.east_asian_width(ch) in 'WF' else 1
            if w==2: cells.append(('', tuple(sorted(cur.items()))))
        grid.append(cells)
