{"command":"cd /workspace && python3 - <<'PY'
import pathlib
p=pathlib.Path("src/main.rs"); t=p.read_text()

# Replace fuzzy_match greedy+score with DP
start=t.find("fn fuzzy_match(query: &str, target: &str) -> Option<(i32, Vec<usize>)> {")
end=t.find("\n}\n", t.find("    Some((score, matched))", start)) + 3
old=t[start:end]
new='''fn fuzzy_match(query: &str, target: &str) -> Option<(i32, Vec<usize>)> {
    let q_chars: Vec<char> = query.chars().collect();
    let t_chars: Vec<char> = target.chars().collect();
    if q_chars.is_empty() { return Some((0, Vec::new())); }
    let case_sensitive = query.chars().any(|c| c.is_uppercase());
    let eq = |a: char, b: char| -> bool {
        if case_sensitive { a == b } else { a.to_lowercase().next().unwrap_or(a) == b.to_lowercase().next().unwrap_or(b) }
    };
    let m = q_chars.len();
    let n = t_chars.len();
    if m > n { return None; }
    // boundary bonus for a matched char at target position t (when it is not a
    // consecutive match, handled by caller).
    let boundary_bonus = |t: usize| -> i32 {
        if t == 0 { 10 } else {
            let p = t_chars[t - 1];
            if p == '/' { 9 } else if matches!(p, '-' | '_' | '.' | ' ') { 3 } else { 0 }
        }
    };
    let char_base = |qi: usize, t: usize| -> i32 {
        let mut s = 10;
        if t_chars[t] == q_chars[qi] { s += 3; } else { s -= 1; }
        s
    };
    // dp[i][t] = best score matching first i+1 query chars ending exactly at target t
    const NEG: i32 = i32::MIN / 4;
    let mut dp = vec![vec![NEG; n]; m];
    let mut pre: Vec<Vec<Option<usize>>> = vec![vec![None; n]; m];
    for t in 0..n {
        if eq(q_chars[0], t_chars[t]) {
            dp[0][t] = char_base(0, t) + boundary_bonus(t);
        }
    }
    for i in 1..m {
        for t in 0..n {
            if !eq(q_chars[i], t_chars[t]) { continue; }
            let mut best = NEG;
            let mut best_prev: Option<usize> = None;
            for pt in 0..t {
                if dp[i - 1][pt] == NEG { continue; }
                let is_boundary = boundary_bonus(t) != 0 || t == 0;
                let mut s = dp[i - 1][pt] + char_base(i, t);
                if is_boundary {
                    s += boundary_bonus(t);
                } else if pt + 1 == t {
                    s += 8;
                }
                if t > pt + 1 { s -= (t - pt - 1) as i32; }
                if s > best { best = s; best_prev = Some(pt); }
            }
            dp[i][t] = best;
            pre[i][t] = best_prev;
        }
    }
    let mut best_score = NEG;
    let mut best_t: Option<usize> = None;
    for t in 0..n {
        if dp[m - 1][t] > best_score { best_score = dp[m - 1][t]; best_t = Some(t); }
    }
    let mut cur = best_t?;
    if best_score == NEG { return None; }
    let mut matched = vec![0usize; m];
    for i in (0..m).rev() {
        matched[i] = cur;
        if i > 0 {
            cur = pre[i][cur]?;
        }
    }
    Some((best_score, matched))
}
'''
